Create the 3-post marketing plan.

parameters.jsCode:
const raw = $input.item.json.output || $input.item.json.text || $input.item.json.message;
const cleaned = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
return { json: JSON.parse(cleaned) };

const posts = $input.all()
  .map(item => item.json)
  .filter(p => p && p.post_type);

if (posts.length === 0) {
  return { json: { error: "שגיאה ביצירת התוכן. אנא נסה שוב." }, statusCode: 500 };
}

return { json: { posts } };
